const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const marovoay = ee.Geometry.Point([46.6347, -16.1110]).buffer(5000); // 5km buffer around Marovoay

  // Date ranges (±1 day to account for potential missing data)
  const date2017 = ['2017-01-17', '2017-01-19'];
  const date2020 = ['2020-01-26', '2020-01-28'];

  // 2. Data Acquisition
  function getWaterCollection(dateRange) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(marovoay)
      .filterDate(dateRange[0], dateRange[1])
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  const col2017 = getWaterCollection(date2017);
  const col2020 = getWaterCollection(date2020);

  // Check collection sizes
  const size2017 = col2017.size().getInfo();
  const size2020 = col2020.size().getInfo();

  console.log(`2017 Images: ${size2017}, 2020 Images: ${size2020}`);

  if (size2017 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first (closest) image for each date
  const img2017 = col2017.first();
  const img2020 = col2020.first();

  // Function to calculate water extent
  function calculateWaterExtent(img) {
    // Calculate NDWI
    const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');

    // Create water mask (NDWI > 0 indicates water)
    const waterMask = ndwi.gt(0);

    // Count water pixels
    const waterCount = waterMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: marovoay,
      scale: 20,
      maxPixels: 1e9
    }).get('NDWI');

    return waterCount;
  }

  const water2017 = calculateWaterExtent(img2017).getInfo();
  const water2020 = calculateWaterExtent(img2020).getInfo();

  console.log(`Water pixels 2017: ${water2017}, 2020: ${water2020}`);

  // Validation checks
  if (water2017 === null || water2020 === null || 
      isNaN(water2017) || isNaN(water2020) ||
      water2017 < 0 || water2020 < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (water2017 === 0 || water2020 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Final comparison
  if (water2020 > water2017) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
